function hitungTotal(harga: number, jumlah: number): number {
  return harga * jumlah;
}
const formatRupiah = (angka: number): string => "Rp" + angka.toLocaleString("id-ID");

const total = hitungTotal(18000, 3);
console.log(total);
console.log(formatRupiah(total));

