function rataRata(nilai: number[]): number {
  return nilai.reduce((a, n) => a + n, 0) / nilai.length;
}
function lulus(nilai: number[]): boolean {
  return rataRata(nilai) >= 75;
}
console.log(rataRata([80, 70, 90]));
console.log(lulus([80, 70, 90]));
console.log(lulus([60, 70, 80]));
